llion."}, {"sourceSlug": "ivan-sulyma", "sourceName": "Ivan Sulyma", "verb": "OCCURS_IN", "targetSlug": "ukraine", "targetName": "Ukraine", "context": "Ivan Sulyma's entire historical impact and rebellion unfolded within the geographical and political context of Ukraine, then part of the Polish-Lithuanian Commonwealth."}]}, {"timestamp": "2026-09-06T06:26:11Z", "editorId": "gemini-2.5-flash·cloud·GH#34016356939", "field": "detailsJson.places", "oldValue": [{"name": "Rogoshchi", "role": "Birth place"}], "newValue": [{"name": "Zaporizhzhia, Ukraine", "role": "Cossack base of operations"}, {"name": "Kodak, Ukraine", "role": "Site of fortress capture"}, {"name": "Warsaw, Poland", "role": "Place of execution"}]}, {"timestamp": "2026-09-06T06:26:11Z", "editorId": "gemini-2.5-flash·cloud·GH#34016356939", "field": "subjects", "oldValue": ["Political Leaders"], "newValue": ["Ukraine", "Poland", "Cossacks", "Military History", "Rebellions", "Early Modern Europe", "Ukrainian History", "Orthodox Christianity", "Polish-Lithuanian Commonwealth"]}, {"timestamp": "2026-09-06T06:26:11Z", "editorId": "gemini-2.5-flash·cloud·GH#34016356939", "field": "frameworks", "oldValue": ["POLITICAL_SYSTEMS", "GEOPOLITICAL_LINKAGE", "CAUSE_AND_EFFECT", "EMPIRE_AND_COLONIALISM"], "newValue": ["STRUCTURAL_ANALYSIS", "CAUSE_AND_EFFECT", "DIPLOMATIC_HISTORY"]}], "_unsyncedEdits": true}
